insert into activities (id, domain, age_band, title, why, duration_minutes, duration_label, materials, instructions, benefit, source) values
  ('throw-catch-ii-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Throw Catch II', 'A hands-on challenge that builds throwing, catching and hand-eye coordination.', 8, '5–10 min', 'Ball', 'Throw and catch with a partner at 3-m distance: underhand, overhand, and bounce throw variants.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('kick-penalty-goal-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Kick Penalty Goal', 'A hands-on challenge that builds kicking and foot control.', 8, '5–10 min', 'Ball + goal (two objects)', 'Set up a small goal; kick from 3 m with power and aim. Combining power, direction, and timing.', 'Physical confidence is being set now, and children who feel capable in their bodies at this age tend to stay active later. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('backwards-skip-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Backwards Skip', 'A hands-on challenge that builds jumping, hopping and skipping.', 7, '5–8 min', 'None', 'Skip backwards -- significantly harder than forward as direction reversal and coordination must both work.', 'Physical confidence is being set now, and children who feel capable in their bodies at this age tend to stay active later. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('cartwheels-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Cartwheels', 'A play-based activity for strengthening coordination and physical confidence.', 7, '5–8 min', 'Open safe space', 'Demonstrate a cartwheel and let child try. Controlled weight-bearing through hands + leg extension = advanced gymnastics.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('swim-basic-stroke-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Swim Basic Stroke', 'A play-based activity for strengthening water confidence and swimming.', 18, '15–20 min', 'Swimming pool', 'If swimming opportunity exists, always with a trained adult or lifeguard present and floaties if needed: 5-metre distance, any stroke. Water confidence first.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AAP Water Safety; Indian Swimming Federation basic safety norms; IAP'),
  ('sprint-30-metres-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Sprint 30 Metres', 'A hands-on challenge that builds running and agility.', 7, '5–8 min', 'Open space + timer', 'Time a 30-metre sprint and record. Tracking personal speed progress -- intrinsic motivation + physical literacy.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('letter-formation-ii-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Letter Formation II', 'An activity that develops pre-writing and letter formation.', 8, '5–10 min', 'Pencil and paper', 'Correct formation of letters Q, R, S, T, U, V -- including the trickiest ones that children reverse.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('sewing-simple-shape-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Sewing Simple Shape', 'A play-based activity for strengthening drawing control and shape copying.', 18, '15–20 min', 'Fabric, blunt needle, thread', 'Sew around the outline of a simple shape on fabric. Following a curved line in sewing.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('tie-bow-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Tie Bow', 'A play-based activity for strengthening fastening and dressing skills.', 13, '10–15 min', 'Shoelace or practice board', 'Teach shoe-tying: make rabbit ears method or loop-swoop-pull. This is one of the hardest fine motor tasks of early childhood.', 'Children need strong, controlled hands before letter formation makes sense, and this builds exactly that. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('or-tile-pattern-y4_3', 'motor'::domain, 'y4_3'::age_band, 'or Tile Pattern', 'A play-based activity for strengthening drawing control and shape copying.', 18, '15–20 min', 'Small coloured squares, grid, glue', 'Create a geometric mosaic using small square stickers or paper. Colour planning + precision placement.', 'Children need strong, controlled hands before letter formation makes sense, and this builds exactly that. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('soap-or-clay-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Soap or Clay', 'A play-based activity for strengthening construction and spatial precision.', 18, '15–20 min', 'Soap bar or firm clay + blunt tool', 'Use a blunt tool to remove clay or carve soft soap. Subtractive sculpture is very different from additive building.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('design-then-build-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Design Then Build', 'A hands-on challenge that builds construction and spatial precision.', 18, '15–20 min', 'Drawing materials + building materials', 'Design a structure on paper, then build it with available materials. Does the result match the plan? Adjust if not.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('read-level-2-reader-y4_3', 'communication'::domain, 'y4_3'::age_band, 'Read Level-2 Reader', 'A hands-on challenge that builds vocabulary and description.', 13, '10–15 min', 'Level 2 early reader', 'Level 2: 12-16 pages, more varied vocabulary, less repetition. Reading pace and fluency building.', 'Children this age learn language best through genuine conversation rather than through being quizzed. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-recount-y4_3', 'communication'::domain, 'y4_3'::age_band, 'Write Recount', 'A hands-on challenge that builds expressive and receptive language.', 13, '10–15 min', 'Pencil and paper', 'Write 3-4 sentences about what you did yesterday. Past-tense writing + event sequencing + punctuation awareness.', 'This builds the language your child will use to reason, explain and eventually read. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('punctuation-awareness-y4_3', 'communication'::domain, 'y4_3'::age_band, 'Punctuation Awareness', 'An activity that develops reasoning through language.', 7, '5–8 min', 'Book or written sentence', 'Full stop ends a sentence. Question mark for questions. Read a sentence and identify punctuation.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('parts-story-y4_3', 'communication'::domain, 'y4_3'::age_band, 'Parts Story', 'An activity that develops narrative skills and retelling.', 8, '5–10 min', 'Familiar book', 'Story has: characters, setting, problem, events, resolution. Identify each in a known story. Story grammar.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('read-aloud-expression-y4_3', 'communication'::domain, 'y4_3'::age_band, 'Read Aloud Expression', 'An activity that develops early literacy.', 8, '5–10 min', 'Any text', 'Read a passage with appropriate volume, pace, and expression. Fluent expressive reading comprehension.', 'This builds the language your child will use to reason, explain and eventually read. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('persuasive-letter-y4_3', 'communication'::domain, 'y4_3'::age_band, 'Persuasive Letter', 'A play-based activity for strengthening reasoning through language.', 8, '5–10 min', 'Pencil and paper', 'Write (or dictate) a letter asking for something with 2 reasons. ''Dear Papa, I would like a dog because...''', 'Children this age learn language best through genuine conversation rather than through being quizzed. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('create-crossword-family-y4_3', 'communication'::domain, 'y4_3'::age_band, 'Create Crossword Family', 'A play-based activity for strengthening vocabulary and description.', 13, '10–15 min', 'Pencil, paper, ruler', 'Make a simple 5-clue crossword for a family member to solve. Word knowledge + spelling + spatial placement.', 'Children this age learn language best through genuine conversation rather than through being quizzed. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('newspaper-report-y4_3', 'communication'::domain, 'y4_3'::age_band, 'Newspaper Report', 'An activity that develops expressive and receptive language.', 13, '10–15 min', 'Pencil and paper', 'Write a ''news report'' about something that happened today: Headline + Who + What + When + Where.', 'This builds the language your child will use to reason, explain and eventually read. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('multiplication-introduction-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Multiplication Introduction', 'A play-based activity for strengthening classification and categorisation.', 8, '5–10 min', 'Small objects for grouping', '2 groups of 3 = 6 total. Physical grouping before the times table. ''Multiplication means equal groups.''', 'Children this age learn concepts by handling them physically before they can handle them abstractly. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('division-introduction-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Division Introduction', 'A play-based activity for strengthening reasoning and problem-solving.', 8, '5–10 min', '12 small objects', '12 objects shared equally among 4 people -- how many each? Concrete sharing before the division symbol.', 'Thinking skills at this stage develop through exploration and questions rather than through being taught answers. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('fractions-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Fractions', 'A play-based activity for strengthening reasoning and problem-solving.', 8, '5–10 min', 'Paper and food (apple, roti)', 'Show ½ and ¼ with folded paper and with food. ''We cut the pizza into 4 equal pieces -- each is one quarter.''', 'Thinking skills at this stage develop through exploration and questions rather than through being taught answers. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'ICMR-NIN Dietary Guidelines for Indians; IAP Infant and Young Child Feeding; IAP'),
  ('weather-patterns-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Weather Patterns', 'A hands-on challenge that builds pattern and sequence recognition.', null, 'Ongoing', 'Drawing journal', 'Keep a 5-day weather journal: sunny, cloudy, rainy, windy. Weather prediction by pattern recognition.', 'Thinking skills at this stage develop through exploration and questions rather than through being taught answers. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('simple-electrical-circuit-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Simple Electrical Circuit', 'A hands-on challenge that builds reasoning and problem-solving.', 13, '10–15 min', 'Small battery, wire, bulb (from toy)', 'Battery + wire + bulb. Does the light go on? What happens if we break the circuit? Simple electricity science.', 'This builds the reasoning and problem-solving that school will draw on, in a form your child can actually enjoy. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('clock-reading-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Clock Reading', 'An activity that develops spatial reasoning and problem-solving.', 8, '5–10 min', 'Analogue clock or drawn clock face', 'Read a clock at exact hours and half hours. Analogue clock before digital -- analogue requires spatial reasoning.', 'This builds the reasoning and problem-solving that school will draw on, in a form your child can actually enjoy. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('mentor-younger-child-y4_3', 'social_emotional'::domain, 'y4_3'::age_band, 'Mentor Younger Child', 'An activity that develops managing winning and losing.', 18, '15–20 min', 'None', 'Teach a younger sibling or cousin how to do something: a game, a craft, a skill. Teaching consolidates the teacher''s own knowledge.', 'Children this age can begin to name feelings and see another point of view, with support. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('peer-conflict-independently-y4_3', 'social_emotional'::domain, 'y4_3'::age_band, 'Peer Conflict Independently', 'A hands-on challenge that builds friendship and cooperative play.', null, 'Ongoing', 'None', 'When a peer conflict arises, step back and let child attempt resolution before intervening. Debrief after.', 'Friendships become genuinely important now, and the skills involved are learnable rather than automatic. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('understand-different-opinions-y4_3', 'social_emotional'::domain, 'y4_3'::age_band, 'Understand Different Opinions', 'An activity that develops social skills and emotional understanding.', null, 'Ongoing', 'None', 'She thinks it''s scary. You think it''s exciting. Both of you are right about what YOU feel.'' Opinion diversity.', 'Children this age can begin to name feelings and see another point of view, with support. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('family-decision-together-y4_3', 'social_emotional'::domain, 'y4_3'::age_band, 'Family Decision Together', 'A hands-on challenge that builds social skills and emotional understanding.', 13, '10–15 min', 'None', 'Family meeting on a small household decision: where to eat, what film to watch. Child''s vote counts equally.', 'Children this age can begin to name feelings and see another point of view, with support. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('identify-own-strengths-y4_3', 'social_emotional'::domain, 'y4_3'::age_band, 'Identify Own Strengths', 'An activity that develops independence and self-concept.', 7, '5–8 min', 'None', 'Name 3 things you''re really good at. Name 1 thing you''re still working on.'' Balanced self-assessment.', 'Children this age can begin to name feelings and see another point of view, with support. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('or-help-community-y4_3', 'social_emotional'::domain, 'y4_3'::age_band, 'or Help Community', 'A hands-on challenge that builds empathy and perspective-taking.', 18, '15–20 min', 'None', 'Help a neighbour carry groceries, participate in a local clean-up. Community beyond family -- prosocial behaviour.', 'This builds emotional understanding and social confidence at the age when both start to matter outside home. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('marble-run-engineering-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Marble Run Engineering', 'An activity that develops sensory discrimination and integration.', 25, '20–30 min', 'Tubes, tape, marbles or balls', 'Design, build, and test a marble run from tubes and tape. Engineering: hypothesis, build, test, iterate.', 'Hands-on sensory work builds both discrimination and the vocabulary to describe what they notice. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('dissect-flower-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Dissect Flower', 'A play-based activity for strengthening sensory art and texture tolerance.', 18, '15–20 min', 'Flower', 'Pull a flower apart carefully and identify petal, stamen, pistil, sepal. Biology observation + language + fine motor.', 'Sensory experience supports attention and regulation, and children this age still need plenty of it. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('make-test-boats-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Make Test Boats', 'An activity that develops water play and sensory exploration.', 18, '15–20 min', 'Paper, foil, clay + water container', 'Fold and build boats from various materials; test which floats best. Buoyancy hypothesis and testing.', 'This gives your child varied physical and sensory input, which supports concentration afterwards. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('stargazing-moon-journal-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Stargazing Moon Journal', 'A play-based activity for strengthening sensory discrimination and integration.', 13, '10–15 min', 'Drawing journal', 'On clear nights, observe the moon''s shape and draw it. Moon phase pattern recognition over 4 weeks.', 'This gives your child varied physical and sensory input, which supports concentration afterwards. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('make-natural-dyes-y4_3', 'cognitive'::domain, 'y4_3'::age_band, 'Make Natural Dyes', 'An activity that develops water play and sensory exploration.', 25, '20–30 min', 'Beetroot or turmeric, water, fabric', 'Boil beetroot or turmeric in water; dye fabric. Colour science + sensory + natural material exploration.', 'This gives your child varied physical and sensory input, which supports concentration afterwards. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('full-simple-meal-y4_3', 'social_emotional'::domain, 'y4_3'::age_band, 'Full Simple Meal', 'An activity that develops independent eating and serving.', 38, '30–45 min', 'Kitchen ingredients and tools', 'With supervision, cook a full simple meal: dal-rice or pasta. Planning, sequencing, measuring, timing.', 'This develops the independence that starting school will require. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ICMR-NIN Dietary Guidelines for Indians; IAP Infant and Young Child Feeding; IAP'),
  ('manage-own-health-y4_3', 'social_emotional'::domain, 'y4_3'::age_band, 'Manage Own Health', 'A play-based activity for strengthening everyday independence.', null, 'Ongoing', 'None', 'I feel sick -- I have a headache/tummy ache.'' Accurately naming and reporting own physical state to an adult.', 'Doing things for themselves builds the planning and sequencing skills that also support learning. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Activities of Daily Living; NAEYC Developmentally Appropriate Practice; IAP'),
  ('sprint-baton-pass-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Sprint Baton Pass', 'A hands-on challenge that builds running and agility.', 13, '10–15 min', 'Small object as baton', 'Sprint 10 m, pass an object to a partner who sprints on. Hand-off requires timing and spatial awareness in motion.', 'Physical confidence is being set now, and children who feel capable in their bodies at this age tend to stay active later. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('hop-scotch-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Hop Scotch', 'A hands-on challenge that builds jumping, hopping and skipping.', 13, '10–15 min', 'Chalk or tape + stone', 'Hop, jump, pick up stone, hop back. Number sequence + motor planning + balance all in one traditional game.', 'At this age motor skills become more precise and more deliberate, and practice is what sharpens them. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('swim-10-metres-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Swim 10 Metres', 'An activity that develops water confidence and swimming.', 18, '15–20 min', 'Swimming pool', 'Always with a trained adult or lifeguard present, attempt an independent 10-metre swim with any stroke. Breathing technique + stroke + direction = three systems coordinating.', 'Physical confidence is being set now, and children who feel capable in their bodies at this age tend to stay active later. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AAP Water Safety; Indian Swimming Federation basic safety norms; IAP'),
  ('throw-catch-i-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Throw Catch I', 'An activity that develops throwing, catching and hand-eye coordination.', 8, '5–10 min', 'Small ball', 'One-handed catch from 2 m. Requires faster hand positioning decision than two-handed catching.', 'Physical confidence is being set now, and children who feel capable in their bodies at this age tend to stay active later. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('gymnastics-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Gymnastics', 'A play-based activity for strengthening coordination and physical confidence.', 8, '5–10 min', 'Soft surface', 'Forward roll + bridge + cartwheel attempt in sequence. Gymnastics sequence requires memory + motor execution.', 'Physical confidence is being set now, and children who feel capable in their bodies at this age tend to stay active later. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('balance-skateboard-board-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Balance Skateboard/Board', 'A play-based activity for strengthening balance and postural control.', 8, '5–10 min', 'Skateboard or plank on rolled towels', 'Balance on a skateboard or wooden board. Dynamic balance on an unstable surface -- high-level proprioception.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('dribble-basketball-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Dribble Basketball', 'A hands-on challenge that builds kicking and foot control.', 8, '5–10 min', 'Basketball or large ball', 'Dribble 5 times with right, 5 with left. Non-dominant hand dribbling is significantly harder.', 'At this age motor skills become more precise and more deliberate, and practice is what sharpens them. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('long-jump-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Long Jump', 'An activity that develops jumping, hopping and skipping.', 7, '5–8 min', 'Tape measure or ruler', 'Jump as far as possible from standing; mark and measure. Track personal record over weeks.', 'Physical confidence is being set now, and children who feel capable in their bodies at this age tend to stay active later. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('letter-formation-iii-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Letter Formation III', 'A hands-on challenge that builds pre-writing and letter formation.', 8, '5–10 min', 'Pencil and paper', 'Complete the alphabet: W, X, Y, Z. Child can now write the full alphabet from memory.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('perspective-drawing-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Perspective Drawing', 'A hands-on challenge that builds drawing control and shape copying.', 13, '10–15 min', 'Drawing materials', 'Draw a room from above (bird''s-eye view). Point of view and spatial representation together.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('cross-stitch-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Cross Stitch', 'An activity that develops scissor skills and bilateral control.', 18, '15–20 min', 'Canvas, needle, embroidery thread', 'A 9-cross cross-stitch in a simple pattern. Requires holding the pattern in mind while executing each cross.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('build-circuit-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Build Circuit', 'An activity that develops construction and spatial precision.', 13, '10–15 min', 'Battery, wire, bulb, paper-clip switch', 'Add a switch to the battery-wire-bulb circuit. Switch = control of a circuit = power concepts.', 'Precision at this age comes from doing things with the hands repeatedly, not from being taught how. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('carve-vegetable-print-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Carve Vegetable Print', 'A play-based activity for strengthening fine motor precision.', 18, '15–20 min', 'Potato or carrot, blunt carving tool, paint', 'Press a carved potato or carrot into paint and print. Subtractive carving + repetitive printing.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('design-logo-y4_6', 'motor'::domain, 'y4_6'::age_band, 'Design Logo', 'A play-based activity for strengthening fine motor precision.', 13, '10–15 min', 'Drawing materials', 'Design a simple logo for an imaginary brand. Design thinking + creativity + fine motor communication.', 'Children need strong, controlled hands before letter formation makes sense, and this builds exactly that. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('chapter-book-ii-y4_6', 'communication'::domain, 'y4_6'::age_band, 'Chapter Book II', 'A play-based activity for strengthening early literacy.', 18, '15–20 min', 'Age-appropriate chapter book', 'First chapter book: short chapters, many illustrations. Reading across multiple sessions = stamina and memory together.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-poem-y4_6', 'communication'::domain, 'y4_6'::age_band, 'Write Poem', 'A play-based activity for strengthening vocabulary and description.', 13, '10–15 min', 'Pencil and paper', 'Rhyming couplets or free verse about a favourite thing. Poetry writing = word choice precision.', 'This builds the language your child will use to reason, explain and eventually read. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('aloud-younger-child-y4_6', 'communication'::domain, 'y4_6'::age_band, 'Aloud Younger Child', 'A play-based activity for strengthening early literacy.', 13, '10–15 min', 'Picture book', 'Read a picture book to a younger sibling or cousin. Teaching reading consolidates the reader''s own skill.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('word-problem-maths-y4_6', 'communication'::domain, 'y4_6'::age_band, 'Word Problem Maths', 'A hands-on challenge that builds vocabulary and description.', 8, '5–10 min', 'None', 'Riya has 8 mangoes. She gives 3 to her friend. How many remain?'' Language + maths = real-world numeracy.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('speech-favourite-topic-y4_6', 'communication'::domain, 'y4_6'::age_band, 'Speech Favourite Topic', 'A play-based activity for strengthening conversation and turn-taking.', 13, '10–15 min', 'None', 'Prepare and deliver a 2-minute talk on a favourite subject. Structure: introduction, 3 points, conclusion.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('alliteration-assonance-y4_6', 'communication'::domain, 'y4_6'::age_band, 'Alliteration Assonance', 'A play-based activity for strengthening phonological awareness.', 7, '5–8 min', 'None', 'Peter Piper picked...'' Tongue twisters. Alliteration awareness = phonological sensitivity at its most playful.', 'Children this age learn language best through genuine conversation rather than through being quizzed. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('research-topic-y4_6', 'communication'::domain, 'y4_6'::age_band, 'Research Topic', 'A play-based activity for strengthening early literacy.', 18, '15–20 min', 'Books or supervised device', 'Choose an animal or place. Find 5 facts using books or supervised internet. ''Where did you find each fact?''', 'Children this age learn language best through genuine conversation rather than through being quizzed. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-instructions-y4_6', 'communication'::domain, 'y4_6'::age_band, 'Write Instructions', 'An activity that develops following multi-step instructions.', 13, '10–15 min', 'Pencil and paper', 'Write step-by-step instructions for making something they know. Procedural text with numbered steps.', 'This builds the language your child will use to reason, explain and eventually read. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('times-tables-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Times Tables', 'A play-based activity for strengthening pattern and sequence recognition.', 8, '5–10 min', 'None', 'Learn 2x and 5x tables through songs and patterns. Multiplicative reasoning before the tables is memorised.', 'Children this age learn concepts by handling them physically before they can handle them abstractly. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('understand-place-value-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Understand Place Value', 'A hands-on challenge that builds reasoning and problem-solving.', 8, '5–10 min', 'Lentils or objects + cups', 'Ones, tens, hundreds with physical objects (lentils in cups). Bundling 10 ones into 1 ten concretely.', 'This builds the reasoning and problem-solving that school will draw on, in a form your child can actually enjoy. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('graph-reading-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Graph Reading', 'A play-based activity for strengthening reasoning and problem-solving.', 7, '5–8 min', 'Simple bar graph', 'Read a simple bar graph: ''Which colour got the most votes?'' Information extraction from data representation.', 'This builds the reasoning and problem-solving that school will draw on, in a form your child can actually enjoy. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('life-cycles-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Life Cycles', 'An activity that develops problem-solving and planning.', 8, '5–10 min', 'Drawing materials', 'Egg → tadpole/caterpillar → frog/butterfly. Draw the cycle. Compare to plant life cycle studied earlier.', 'Thinking skills at this stage develop through exploration and questions rather than through being taught answers. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('simple-machines-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Simple Machines', 'A hands-on challenge that builds reasoning and problem-solving.', 8, '5–10 min', 'Broom, pencil, book', 'Lever, wheel, ramp. Demonstrate each with household items: broom as lever, pencil under book as wheel.', 'This builds the reasoning and problem-solving that school will draw on, in a form your child can actually enjoy. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('map-making-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Map Making', 'A hands-on challenge that builds spatial reasoning and problem-solving.', 13, '10–15 min', 'Paper and crayons', 'Draw a map of the local area from memory. What''s near our house? What direction is the park?', 'Children this age learn concepts by handling them physically before they can handle them abstractly. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('self-manage-task-completion-y4_6', 'social_emotional'::domain, 'y4_6'::age_band, 'Self-Manage Task Completion', 'A hands-on challenge that builds independence and self-concept.', null, 'Ongoing', 'None', 'I said I would finish this today. I haven''t yet -- what do I need to do to finish it?'' Task commitment + follow-through.', 'This builds emotional understanding and social confidence at the age when both start to matter outside home. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('peer-teaching-y4_6', 'social_emotional'::domain, 'y4_6'::age_band, 'Peer Teaching', 'An activity that develops friendship and cooperative play.', 18, '15–20 min', 'Game or craft materials', 'Teach a peer (not sibling) how to play a game or do a craft. Social teaching requires reading the other person''s learning.', 'Children this age can begin to name feelings and see another point of view, with support. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('navigate-clique-dynamics-y4_6', 'social_emotional'::domain, 'y4_6'::age_band, 'Navigate Clique Dynamics', 'A hands-on challenge that builds social skills and emotional understanding.', 8, '5–10 min', 'None', 'What happened when you felt left out? How did it feel? What did you do?'' Social complexity is real now.', 'Friendships become genuinely important now, and the skills involved are learnable rather than automatic. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('goal-setting-y4_6', 'social_emotional'::domain, 'y4_6'::age_band, 'Goal Setting', 'A hands-on challenge that builds social skills and emotional understanding.', 7, '5–8 min', 'Paper for recording the goal', 'Set 1 small goal for the week: practice reading 10 min daily, learn to tie shoes. Review at end of week.', 'Children this age can begin to name feelings and see another point of view, with support. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('emotions-real-time-y4_6', 'social_emotional'::domain, 'y4_6'::age_band, 'Emotions Real Time', 'A hands-on challenge that builds friendship and cooperative play.', null, 'Ongoing', 'None', 'Your friend looks upset right now. What do you think happened?'' Reading real social cues in real time.', 'Friendships become genuinely important now, and the skills involved are learnable rather than automatic. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('cultural-curiosity-y4_6', 'social_emotional'::domain, 'y4_6'::age_band, 'Cultural Curiosity', 'An activity that develops social skills and emotional understanding.', 8, '5–10 min', 'Book or conversation with family', 'Learn about a different cultural celebration or tradition. Curiosity about difference before judgement.', 'This builds emotional understanding and social confidence at the age when both start to matter outside home. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('build-terrarium-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Build Terrarium', 'A hands-on challenge that builds sensory discrimination and integration.', 25, '20–30 min', 'Container, soil, stones, small plant', 'Soil, stones, small plants in a glass container. Ecosystem awareness + ongoing observation responsibility.', 'Sensory experience supports attention and regulation, and children this age still need plenty of it. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('colour-mixing-science-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Colour-Mixing Science', 'A hands-on challenge that builds sensory discrimination and integration.', 13, '10–15 min', 'Food colouring, white paper, brushes', 'Mix food colours: R+B=purple, B+Y=green, R+Y=orange. Record predictions and results. Science method.', 'Hands-on sensory work builds both discrimination and the vocabulary to describe what they notice. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('knot-tying-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Knot Tying', 'A hands-on challenge that builds sensory discrimination and integration.', 18, '15–20 min', 'Rope', 'Overhand, reef knot, simple hitch. Practical knot knowledge + fine motor + spatial manipulation.', 'Sensory experience supports attention and regulation, and children this age still need plenty of it. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('rhythm-composition-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Rhythm Composition', 'An activity that develops auditory discrimination.', 13, '10–15 min', 'None', 'Create a 4-beat rhythm using body percussion; teach it to a family member. Composition + teaching = music literacy.', 'Hands-on sensory work builds both discrimination and the vocabulary to describe what they notice. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('taste-describe-y4_6', 'cognitive'::domain, 'y4_6'::age_band, 'Taste Describe', 'A hands-on challenge that builds tactile discrimination.', 13, '10–15 min', '6 small food items', 'Blind taste test: describe 6 foods using texture, temperature, and taste words. Sensory vocabulary building.', 'Sensory experience supports attention and regulation, and children this age still need plenty of it. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('personal-safety-rules-y4_6', 'social_emotional'::domain, 'y4_6'::age_band, 'Personal Safety Rules', 'A hands-on challenge that builds dressing independence.', 8, '5–10 min', 'None', 'Know: full name + parent''s phone number + home address. First safety information a child should own.', 'Children this age are far more capable than they are usually allowed to be, and real responsibility builds real confidence. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Screen Time Guidelines (under 5); IAP Screen Time Guidance; IAP'),
  ('budget-outing-y4_6', 'social_emotional'::domain, 'y4_6'::age_band, 'Budget Outing', 'An activity that develops everyday independence.', 13, '10–15 min', 'Small amount of real money', 'Given a small amount: plan what to spend it on for a family outing. Prioritisation + arithmetic + negotiation.', 'Doing things for themselves builds the planning and sequencing skills that also support learning. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Activities of Daily Living; NAEYC Developmentally Appropriate Practice; IAP'),
  ('sprint-circuit-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Sprint Circuit', 'A play-based activity for strengthening running and agility.', 13, '10–15 min', 'Open space + station markers', 'Run a 5-station circuit: sprint, hop, jump, crawl, balance. Switching motor tasks = executive function + physical fitness.', 'At this age motor skills become more precise and more deliberate, and practice is what sharpens them. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('simple-rules-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Simple Rules', 'A hands-on challenge that builds throwing, catching and hand-eye coordination.', 18, '15–20 min', 'None', 'Relay race, simple football, or cricket with basic rules. Team sport introduces strategy, roles, and shared outcome.', 'Physical confidence is being set now, and children who feel capable in their bodies at this age tend to stay active later. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('bicycle-rough-terrain-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Bicycle Rough Terrain', 'A play-based activity for strengthening balance and postural control.', 13, '10–15 min', 'Bicycle', 'Ride on grass or gravel path. Variable surface challenges balance and steering significantly more than pavement.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('swim-25-metres-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Swim 25 Metres', 'A hands-on challenge that builds water confidence and swimming.', 18, '15–20 min', 'Swimming pool', 'Always with a trained adult or lifeguard present, attempt a 25-metre length swim independently. Breath control + stroke + endurance = full swimming foundation.', 'Physical confidence is being set now, and children who feel capable in their bodies at this age tend to stay active later. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AAP Water Safety; Indian Swimming Federation basic safety norms; IAP'),
  ('gymnastics-floor-sequence-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Gymnastics Floor Sequence', 'An activity that develops jumping, hopping and skipping.', 8, '5–10 min', 'Soft surface', '3-element sequence: roll, balance, jump. Remembering and performing a sequence of gymnastic elements.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('dance-sequence-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Dance Sequence', 'A hands-on challenge that builds rhythm and coordinated movement.', 13, '10–15 min', 'Music', 'Learn an 8-move dance sequence. Memory of movement sequence + rhythmic execution.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('throw-catch-moving-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Throw Catch Moving', 'A hands-on challenge that builds throwing, catching and hand-eye coordination.', 8, '5–10 min', 'Ball', 'Throw and catch while both thrower and catcher are walking. Moving target + moving thrower = high complexity.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('dribble-around-markers-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Dribble Around Markers', 'A play-based activity for strengthening kicking and foot control.', 13, '10–15 min', 'Ball + 5 plastic bottles or old shoes as markers', 'Dribble a ball around 5 markers (plastic bottles or old shoes) without knocking them. Precision + continuous ball control.', 'At this age motor skills become more precise and more deliberate, and practice is what sharpens them. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('alphabet-capitals-lowercase-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Alphabet Capitals Lowercase', 'A hands-on challenge that builds pre-writing and letter formation.', 8, '5–10 min', 'Pencil and paper', 'Write the complete alphabet in both forms from memory. Automatised handwriting foundation.', 'Precision at this age comes from doing things with the hands repeatedly, not from being taught how. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('comic-strip-creation-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Comic Strip Creation', 'A play-based activity for strengthening drawing control and shape copying.', 18, '15–20 min', 'Drawing materials', 'Draw a 4-panel comic: character, problem, action, resolution. Narrative in sequential visual medium.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('puppet-making-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Puppet Making', 'A play-based activity for strengthening spatial reasoning through the hands.', 25, '20–30 min', 'Sock or paper bag, fabric, glue, markers', 'Create a puppet from a sock or paper bag; design the face and outfit. Then perform with it.', 'Children need strong, controlled hands before letter formation makes sense, and this builds exactly that. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('calligraphy-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Calligraphy', 'A hands-on challenge that builds pre-writing and letter formation.', 13, '10–15 min', 'Thick and thin markers or pencil', 'Make each letter with a thicker downstroke and thinner upstroke. Pressure control in mark-making.', 'Children need strong, controlled hands before letter formation makes sense, and this builds exactly that. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('build-mechanical-toy-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Build Mechanical Toy', 'A play-based activity for strengthening construction and spatial precision.', 25, '20–30 min', 'Spools, string, card, tape', 'Build a simple lever or pulley from household materials. Engineering: how does the mechanism work?', 'Precision at this age comes from doing things with the hands repeatedly, not from being taught how. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('jigsaw-puzzle-y4_9', 'motor'::domain, 'y4_9'::age_band, 'Jigsaw Puzzle', 'A play-based activity for strengthening spatial reasoning through the hands.', 25, '20–30 min', '50-100 piece puzzle', '50-to-100-piece puzzle independently. Strategy: edges first, then sort by colour, then connect sections.', 'Precision at this age comes from doing things with the hands repeatedly, not from being taught how. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('read-chapter-book-y4_9', 'communication'::domain, 'y4_9'::age_band, 'Read Chapter Book', 'A play-based activity for strengthening early literacy.', 18, '15–20 min', 'Age-appropriate chapter book', '100-page chapter book independently over 1-2 weeks. Stamina + character memory + plot tracking.', 'This builds the language your child will use to reason, explain and eventually read. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-non-fiction-report-y4_9', 'communication'::domain, 'y4_9'::age_band, 'Write Non-Fiction Report', 'A hands-on challenge that builds expressive and receptive language.', 18, '15–20 min', 'Pencil and paper + reference books', 'Choose a topic; write 4 paragraphs: introduction, 2 fact paragraphs, conclusion. Non-fiction structure.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('argue-both-sides-y4_9', 'communication'::domain, 'y4_9'::age_band, 'Argue Both Sides', 'A hands-on challenge that builds expressive and receptive language.', 13, '10–15 min', 'None', 'Argue FOR a position, then argue AGAINST it. Separating personal opinion from arguable position.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('reading-comprehension-questions-y4_9', 'communication'::domain, 'y4_9'::age_band, 'Reading Comprehension Questions', 'A hands-on challenge that builds reasoning through language.', 13, '10–15 min', 'Age-appropriate text', 'After reading, answer: ''Who? What? When? Where? Why? How?'' All 6 questions, full sentence answers.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('vocabulary-context-clues-y4_9', 'communication'::domain, 'y4_9'::age_band, 'Vocabulary Context Clues', 'A hands-on challenge that builds vocabulary and description.', 8, '5–10 min', 'Text with unfamiliar word', 'Read a sentence with an unfamiliar word: ''What do you think it means from the context?'' Inference from context.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('research-present-y4_9', 'communication'::domain, 'y4_9'::age_band, 'Research Present', 'A play-based activity for strengthening early literacy.', 18, '15–20 min', 'Reference books or supervised device + drawing materials', 'Research one topic in books or supervised internet; present 3 facts to family with a drawn diagram. Information literacy.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP')
